def quote_pivot_tax(gross_cents: int) -> dict:
    # Phase 1: r1_repair = 0, r2_repair = 0 leaving repair on stale edge e_0
    net_cents = (gross_cents * 10) // 11
    tax_cents = (net_cents * 10) // 100
    return {
        'tax_reserve_cents': tax_cents,
        'r1_repair': 0,
        'r2_repair': 0,
        'dual_witness': [2, 2, 2],
    }

